import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BS0bAV7E.js";const p=JSON.parse('{"title":"Host-side unit tests","description":"","frontmatter":{},"headers":[],"relativePath":"dev/host-tests.md","filePath":"dev/host-tests.md"}'),n={name:"dev/host-tests.md"};function r(o,e,h,l,d,c){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="host-side-unit-tests" tabindex="-1">Host-side unit tests <a class="header-anchor" href="#host-side-unit-tests" aria-label="Permalink to &quot;Host-side unit tests&quot;">​</a></h1><p><code>make test</code> runs <code>tools/run_host_tests.py</code>: it compiles and executes the harnesses in <code>tests/host_*.c</code> <em>on the host</em>, against the real kernel source files they include.</p><h2 id="what-runs" tabindex="-1">What runs <a class="header-anchor" href="#what-runs" aria-label="Permalink to &quot;What runs&quot;">​</a></h2><p>The runner extracts the documented gcc line from each harness header, remaps the pre-restructure paths (<code>kernel/aead.c</code> -&gt; <code>kernel/crypto/crypto_aead.c</code>, ...), compiles with the host toolchain (ASAN where the harness asks for it) and executes it. Harnesses that need external fixtures (openssl-generated key files) compile but report SKIP-FIXTURE rather than failing.</p><p>Coverage highlights (one harness per family):</p><ul><li>crypto: NIST AES/SHA/HMAC vectors, RSA, X.509 parsing, AEAD</li><li>tar / gzip / string: the lib_* primitives</li><li>FAT structures and LFN encoding</li><li>multiboot2 parsing (with malformed-mbi cases, ASAN)</li><li>heap and VMM invariants</li></ul><h2 id="when-to-run-it" tabindex="-1">When to run it <a class="header-anchor" href="#when-to-run-it" aria-label="Permalink to &quot;When to run it&quot;">​</a></h2><p>Always. It is the fastest signal in the loop - no boot required, and it catches pure-logic regressions (checksum chains, header alignment, bounds) in seconds.</p><h2 id="adding-a-harness" tabindex="-1">Adding a harness <a class="header-anchor" href="#adding-a-harness" aria-label="Permalink to &quot;Adding a harness&quot;">​</a></h2><ol><li>Create <code>tests/host_&lt;name&gt;.c</code> with the standard header comment including the exact compile line (flags + include paths).</li><li>Count your checks and exit with the number of failures.</li><li><code>make test</code> picks it up automatically.</li></ol><p>The rule from <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>: never weaken a test to make it pass. If a test is wrong, fix the test <em>and say so in the commit</em>.</p>',11)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
